Given the Inorder and Postorder traversals of a binary tree, the task is to find the Preorder traversal. Examples:Input: post[] = [4, 5, 2, 6, 3, 1]            in[] = [4, 2, 5, 1, 3, 6]Output: 1 2 4 5 3 6Explanation: Traversals in the above example represents following tree:The idea is to first construct the binary tree from a given postorder and inorder, then use a simple recursive method to print the preorder traversal of the constructed tree.Note: We can optimize the above method. We do not need to create the tree.Table of Content[Naive approach] Search current element every time - O(n^2) Time and O(n) Space[Expected approach] Using hashing - O(n) Time and O(n) Space[Naive approach] Search current element every time - O(n^2) Time and O(n) Space The idea is that root is always the first item in preorder traversal and it must be the last item in postorder traversal. We first push right subtree to a stack, then left subtree, and finally, we push root. Finally, we print contents of stack. To find boundaries of left and right subtrees in post[] and in[], we search root in in[], all elements before root in in[] are elements of left subtree, and all elements after root are elements of right subtree. In post[], all elements after index of root in in[] are elements of right subtree. And elements before index (including the element at index and excluding the first element) are elements of left subtree. Below is the implementation of the above approach: 
            C++

    // C++ program to print Postorder traversal from given
// Inorder and Preorder traversals.

#include<bits/stdc++.h>
using namespace std; 

// A utility function to search data in in[]
int search(vector<int>& in, int data, int n) {
    int i = 0;
    for (i = 0; i < n; i++)
        if (in[i] == data)
            return i;
    return i;
}

// Fills preorder traversal of tree with given
// inorder and postorder traversals in a stack
void fillPre(vector<int>& in, vector<int>& post, int inStrt,
            int inEnd, stack<int> &s, int n, int &postIndex) {
    if (inStrt > inEnd)
        return;

    // Find index of next item in postorder traversal in
    // inorder.
    int val = post[postIndex];
    int inIndex = search(in, val, n);
    postIndex--;

    // traverse right tree
    fillPre(in, post, inIndex + 1, inEnd, s, n, postIndex);

    // traverse left tree
    fillPre(in, post, inStrt, inIndex - 1, s, n, postIndex);

    s.push(val);
}

// This function basically initializes postIndex
// as last element index, then fills stack with
// reverse preorder traversal using printPre
vector<int> getPreorderTraversal(vector<int>& in, vector<int>& post, int n) {
    int len = n;
    int postIndex = len - 1;
    stack<int> s;
    fillPre(in, post, 0, len - 1, s, n, postIndex);	
  	vector<int> result;
    while (s.size() > 0) {
      	result.push_back(s.top());
        s.pop();
    }
  	return result;
}

int main() {
    vector<int> in = { 4, 2, 5, 1, 3, 6 };
    vector<int> post = { 4, 5, 2, 6, 3, 1 };
    int n = in.size();
    vector<int> result = getPreorderTraversal(in, post, n);
  	for(int i : result) {
    	cout << i << " ";
    }
}


