        List<Integer> in = Arrays.asList(4, 2, 5, 1, 3, 6);
        List<Integer> post = Arrays.asList(4, 5, 2, 6, 3, 1);
        int n = in.size();

        List<Integer> result = getPreorderTraversal(in, post, n);

        for (int i : result) {
            System.out.print(i + " ");
        }
    }
}


